import networkx as nx
from itertools import combinations

def solve_small_n(n):
    # Create the king's graph for n x n
    G = nx.Graph()
    for i in range(n):
        for j in range(n):
            G.add_node((i, j))

    for i in range(n):
        for j in range(n):
            for di in [-1, 0, 1]:
                for dj in [-1, 0, 1]:
                    if di == 0 and dj == 0:
                        continue
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < n:
                        G.add_edge((i, j), (ni, nj))

    # We want to find the maximum size of a subset S such that the induced subgraph has max degree 1.
    # This is an NP-hard problem in general, but for small n we can use brute force or a solver.
    # Since we are looking for a maximum, we can try k from n*n down to 1.

    import itertools

    nodes = list(G.nodes())
    for k in range(n * n, 0, -1):
        for S in itertools.combinations(nodes, k):
            subgraph = G.subgraph(S)
            if all(deg <= 1 for node, deg in subgraph.degree()):
                return k
    return 0

for n in range(1, 5):
    print(f"n={n}, k={solve_small_n(n)}")

def get_neighbors(n, r, c):
    neighbors = []
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                neighbors.append((nr, nc))
    return neighbors

def solve_recursive(n):
    best_k = 0

    def is_valid(S, r, c):
        # Check if adding (r, c) to S keeps max degree <= 1
        # 1. (r, c) must have at most 1 neighbor in S
        neighbors_in_S = 0
        for nr, nc in get_neighbors(n, r, c):
            if (nr, nc) in S:
                neighbors_in_S += 1
                # 2. That neighbor must have no other neighbors in S
                for nnr, nnc in get_neighbors(n, nr, nc):
                    if (nnr, nnc) in S and (nnr, nnc) != (r, c):
                        return False
        return neighbors_in_S <= 1

    def backtrack(r, c, S):
        nonlocal best_k
        if r == n:
            best_k = max(best_k, len(S))
            return

        next_r, next_c = (r, c + 1) if c + 1 < n else (r + 1, 0)

        # Option 1: Pick (r, c)
        if is_valid(S, r, c):
            S.add((r, c))
            backtrack(next_r, next_c, S)
            S.remove((r, c))

        # Option 2: Don't pick (r, c)
        # Pruning: if we don't pick (r, c), can we still reach best_k?
        remaining = (n * n) - (r * n + c + 1)
        if len(S) + remaining > best_k:
            backtrack(next_r, next_c, S)

    backtrack(0, 0, set())
    return best_k

